import{_ as l,o as e,c as i,ag as t}from"./chunks/framework.H6YukQLu.js";const g=JSON.parse('{"title":"我的 2026 年学习计划","description":"","frontmatter":{"title":"我的 2026 年学习计划","date":"2026-03-28T00:00:00.000Z","tags":["随笔","成长"],"category":"随笔"},"headers":[],"relativePath":"posts/2026-learning-plan.md","filePath":"posts/2026-learning-plan.md","lastUpdated":1777182093000}'),r={name:"posts/2026-learning-plan.md"};function o(n,a,s,h,d,u){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="我的-2026-年学习计划" tabindex="-1">我的 2026 年学习计划 <a class="header-anchor" href="#我的-2026-年学习计划" aria-label="Permalink to &quot;我的 2026 年学习计划&quot;">​</a></h1><p>新的一年，给自己定下一些学习目标，希望能在技术上有所突破。</p><h2 id="技术学习" tabindex="-1">技术学习 <a class="header-anchor" href="#技术学习" aria-label="Permalink to &quot;技术学习&quot;">​</a></h2><h3 id="前端深入" tabindex="-1">前端深入 <a class="header-anchor" href="#前端深入" aria-label="Permalink to &quot;前端深入&quot;">​</a></h3><ul><li><strong>Vue 3 生态</strong> - 深入理解响应式原理，掌握 Pinia、Vue Router</li><li><strong>TypeScript</strong> - 提升类型编程能力，学习高级类型技巧</li><li><strong>构建工具</strong> - 深入 Vite、Webpack 原理</li><li><strong>CSS</strong> - 掌握 Tailwind CSS，学习 CSS-in-JS 方案</li></ul><h3 id="后端拓展" tabindex="-1">后端拓展 <a class="header-anchor" href="#后端拓展" aria-label="Permalink to &quot;后端拓展&quot;">​</a></h3><ul><li><strong>Node.js</strong> - 学习 Nest.js 框架</li><li><strong>数据库</strong> - 深入 PostgreSQL，学习 Redis</li><li><strong>Docker</strong> - 容器化部署实践</li></ul><h3 id="新技术探索" tabindex="-1">新技术探索 <a class="header-anchor" href="#新技术探索" aria-label="Permalink to &quot;新技术探索&quot;">​</a></h3><ul><li><strong>AI 应用开发</strong> - 学习 LLM API 集成</li><li><strong>Rust</strong> - 入门学习，理解内存安全</li><li><strong>WebAssembly</strong> - 了解应用场景</li></ul><h2 id="读书计划" tabindex="-1">读书计划 <a class="header-anchor" href="#读书计划" aria-label="Permalink to &quot;读书计划&quot;">​</a></h2><h3 id="技术书籍" tabindex="-1">技术书籍 <a class="header-anchor" href="#技术书籍" aria-label="Permalink to &quot;技术书籍&quot;">​</a></h3><ul><li>《JavaScript 高级程序设计》- 重读经典</li><li>《设计模式》- 理解常用模式</li><li>《代码整洁之道》- 提升代码质量</li></ul><h3 id="非技术书籍" tabindex="-1">非技术书籍 <a class="header-anchor" href="#非技术书籍" aria-label="Permalink to &quot;非技术书籍&quot;">​</a></h3><ul><li>《深度工作》- 提升专注力</li><li>《系统之美》- 理解系统思维</li></ul><h2 id="项目实践" tabindex="-1">项目实践 <a class="header-anchor" href="#项目实践" aria-label="Permalink to &quot;项目实践&quot;">​</a></h2><h3 id="个人项目" tabindex="-1">个人项目 <a class="header-anchor" href="#个人项目" aria-label="Permalink to &quot;个人项目&quot;">​</a></h3><ol><li><strong>博客系统</strong> - 持续优化，添加评论、搜索功能</li><li><strong>工具库</strong> - 封装常用工具函数，发布 npm 包</li><li><strong>开源贡献</strong> - 参与感兴趣的开源项目</li></ol><h3 id="技术写作" tabindex="-1">技术写作 <a class="header-anchor" href="#技术写作" aria-label="Permalink to &quot;技术写作&quot;">​</a></h3><ul><li>每周至少一篇技术文章</li><li>记录学习笔记和踩坑经验</li><li>整理知识体系</li></ul><h2 id="健康生活" tabindex="-1">健康生活 <a class="header-anchor" href="#健康生活" aria-label="Permalink to &quot;健康生活&quot;">​</a></h2><ul><li>每周运动 3 次以上</li><li>保持规律作息</li><li>减少无效社交</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>计划赶不上变化，但有了目标就有了方向。希望 2026 年能成为一个更好的自己！</p>',23)])])}const b=l(r,[["render",o]]);export{g as __pageData,b as default};
